/* CHEM-MAP TUTOR AI 2.0 — local-first executable demo. All example student accounts are mock identities. */
(()=>{
'use strict';
const DB='chemmap2-local-v1';
const bank=window.CHEM_BANK,engine=window.CMEngine;
const base=bank.questions;
const el=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const nl=s=>esc(s).replace(/\n/g,'<br>');
const date=s=>new Date(s).toLocaleString('vi-VN',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'});
const number=x=>Number(x||0).toLocaleString('vi-VN',{maximumFractionDigits:2});
const code=()=>Math.random().toString(36).slice(2,9);
const allQuestions=()=>base.concat((state.customQuestions||[]).filter(q=>q.approved)).filter(x=>!state.archived?.includes(x.id));
const student=()=>state.students.find(x=>x.id===state.studentId)||state.students[0];
const attempts=()=>state.attempts.filter(x=>x.studentId===state.studentId);
const roleNames={student:'Học sinh',teacher:'Giáo viên',admin:'Quản trị'};
const navs=[
{id:'overview',icon:'⌂',title:'Tổng quan'},
{id:'practice',icon:'◫',title:'Luyện tập thông minh'},
{id:'exams',icon:'☷',title:'Đề kiểm tra'},
{id:'mistakes',icon:'◎',title:'Bản đồ lỗi sai'},
{id:'learning',icon:'↗',title:'Lộ trình cá nhân'},
{id:'library',icon:'▤',title:'Kho câu hỏi Hóa 10–12'},
{id:'jigsaw',icon:'▧',title:'Phiếu học tập Jigsaw',roles:['teacher','admin']},
{id:'teacher',icon:'▦',title:'Không gian giáo viên',roles:['teacher','admin']},
{id:'reports',icon:'▥',title:'Thống kê & minh chứng',roles:['teacher','admin']},
{id:'admin',icon:'⚙',title:'Dữ liệu & hệ thống',roles:['admin','teacher']},
{id:'about',icon:'ⓘ',title:'Giới thiệu & quy trình'}];
const fresh=()=>({role:'student',studentId:'hs-01',students:[{id:'hs-01',name:'Học sinh demo A',grade:11},{id:'hs-02',name:'Học sinh demo B',grade:10},{id:'hs-03',name:'Học sinh demo C',grade:12}],customQuestions:[],archived:[],attempts:[],assignments:[],interventions:[],activeQuiz:null,latestAttemptId:null});
function load(){try{const data=JSON.parse(localStorage.getItem(DB)||'null');if(data&&Array.isArray(data.students)&&Array.isArray(data.attempts)&&Array.isArray(data.customQuestions))return {...fresh(),...data}}catch(e){console.warn(e)}return fresh()}
let state=load();const ui={view:'overview',grade:Number(student()?.grade||11),chapter:'all',type:'all',level:'all',count:'8',libraryGrade:'all',libraryChapter:'all',teacherTab:'dashboard',attemptId:null,filterStudent:'all'};
function persist(){try{localStorage.setItem(DB,JSON.stringify(state));}catch(e){toast('Bộ nhớ trình duyệt đã đầy. Hãy xuất dữ liệu trước khi tiếp tục.')}}
function toast(message){const t=el('toast');t.textContent=message;t.classList.add('show');clearTimeout(toast._id);toast._id=setTimeout(()=>t.classList.remove('show'),3600)}
function levelChip(level){return `<span class="chip ${({'Nhận biết':'n','Thông hiểu':'h','Vận dụng':'v','Vận dụng cao':'c'})[level]||''}">${esc(level)}</span>`}
function typeName(type){return ({mcq:'Nhiều phương án',tf:'Đúng / Sai',short:'Trả lời ngắn',essay:'Tự luận'})[type]||type}
function pill(text,css=''){return `<span class="chip ${css}">${esc(text)}</span>`}
function empty(message,action){return `<div class="empty"><span class="big">◌</span>${esc(message)}${action?`<div class="btn-row" style="justify-content:center"><button class="btn primary" data-nav="${action}">Bắt đầu luyện tập →</button></div>`:''}</div>`}
function pageHeader(kicker,title,description){return `<div class="section-top"><p class="h-overline">${esc(kicker)}</p><h1 class="page-title">${esc(title)}</h1><p class="page-intro">${esc(description)}</p></div>`}
function progress(skill,pct,meta=''){return `<div class="progress-row"><div class="progress-top"><span>${esc(skill)}</span><span>${Math.round(pct)}%</span></div><div class="bar"><div class="bar-fill" style="width:${Math.max(0,Math.min(100,pct))}%"></div></div>${meta?`<div class="progress-meta">${esc(meta)}</div>`:''}</div>`}
function topnav(){el('nav-main').innerHTML=navs.filter(n=>!n.roles||n.roles.includes(state.role)).map(n=>`<button class="nav-item ${ui.view===n.id?'active':''}" data-nav="${n.id}"><span class="nav-symbol">${n.icon}</span>${n.title}</button>`).join('')}
function header(){el('page-heading').textContent=navs.find(x=>x.id===ui.view)?.title||'CHEM-MAP';el('role-switch').value=state.role;el('student-holder').style.display=state.role==='student'?'flex':'none';el('student-switch').innerHTML=state.students.map(s=>`<option value="${esc(s.id)}" ${s.id===state.studentId?'selected':''}>${esc(s.name)}</option>`).join('');}
function render(){if(state.activeQuiz){el('content').innerHTML=quizView();el('page-heading').textContent='Đang làm bài';topnav();header();el('page-heading').textContent='Đang làm bài';return;}
 const routes={overview:renderOverview,practice:renderPractice,exams:renderExams,mistakes:renderMistakes,learning:renderLearning,library:renderLibrary,jigsaw:()=>window.CMJigsaw.render(),teacher:renderTeacher,reports:renderReports,admin:renderAdmin,about:renderAbout,result:renderResult};if((['teacher','reports','admin','jigsaw'].includes(ui.view))&&state.role==='student')ui.view='overview';el('content').innerHTML=(routes[ui.view]||renderOverview)();topnav();header();}
function navigate(view){if(state.activeQuiz){if(!confirm('Bạn đang làm bài. Rời trang sẽ giữ phiên làm bài hiện tại. Bạn muốn chuyển trang sau khi hoàn tất?'))return;toast('Hãy nộp bài hoặc hủy phiên làm bài hiện tại.');return;}ui.view=view;ui.attemptId=null;el('sidebar').classList.remove('open');render();window.scrollTo(0,0)}
function metric(icon,value,label,tone=''){return `<div class="metric"><div class="metric-icon ${tone}">${icon}</div><div><div class="metric-value">${esc(value)}</div><div class="metric-label">${esc(label)}</div></div></div>`}
function renderOverview(){const my=attempts(),graded=my.filter(x=>x.graded);const latest=my.at(-1),av=graded.length?graded.reduce((sum,a)=>sum+a.score,0)/graded.length:null;const allGradeQs=allQuestions().filter(x=>x.grade===Number(student().grade)).length;let mastery=engine.mastery(state.attempts,state.studentId);
 return `<div class="welcome"><div><div class="eyebrow">HỌC HIỂU BẢN CHẤT · SỬA ĐÚNG LỖI SAI</div><h1>Chào mừng đến với CHEM-MAP TUTOR AI 2.0</h1><p>Không chỉ cho biết đúng hay sai: hệ thống đối chiếu phương án nhiễu, giải thích cơ chế nhầm lẫn có căn cứ và hướng dẫn học tập theo dữ liệu thực tế.</p><div class="btn-row"><button class="btn teal" data-nav="practice">Bắt đầu luyện tập →</button><button class="btn secondary" data-nav="learning">Xem lộ trình học</button></div></div><div class="hero-icon" aria-hidden="true"><svg viewBox="0 0 120 120"><path d="M42 13h36M54 13v33L27 94a8 8 0 0 0 7 12h52a8 8 0 0 0 7-12L66 46V13"/><path d="M37 79h46"/><circle cx="51" cy="70" r="4"/><circle cx="69" cy="90" r="5"/><circle cx="62" cy="59" r="2"/></svg></div></div>
 <div class="metrics">${metric('▤',allQuestions().length,'Câu hỏi học liệu đã nạp')}${metric('◉',my.length,'Lượt làm bài của '+student().name,'teal')}${metric('◈',av==null?'—':`${number(av)}/10`,'Điểm trung bình bài đã chấm','purple')}${metric('◷',my.filter(a=>a.pendingCount).length,'Bài đang chờ chấm tự luận','amber')}</div>
 <div class="heading"><div><h2>Không gian học tập cá nhân</h2><p>Đi từ chẩn đoán đến khắc phục lỗi theo từng khối lớp.</p></div><span class="chip">Khối ${student().grade} · ${allGradeQs} câu</span></div>
 <div class="layout-two"><section class="card"><div class="card-head"><h3>Bản đồ năng lực theo kỹ năng</h3><button class="btn sm secondary" data-nav="mistakes">Chi tiết →</button></div>${mastery.length?mastery.slice(0,6).map(m=>progress(m.skill,m.percent,`${m.items} câu đã chấm · ${m.reliability}`)).join(''):empty('Chưa có dữ liệu chẩn đoán. Hãy làm bài đầu tiên.','practice')}</section>
 <section class="card"><h3>Tiến độ gần nhất</h3>${latest?`<div class="mini-grid"><div><b>${number(latest.score)}/10</b><span>${latest.graded?'Điểm chính thức':'Điểm tạm tính'}</span></div><div><b>${latest.questions.length}</b><span>Câu hỏi</span></div><div><b>${latest.incorrect}</b><span>Câu chưa đạt</span></div></div><p class="p-lead">${esc(latest.title)} · ${date(latest.createdAt)}</p><button class="btn secondary" data-action="view-attempt" data-id="${latest.id}">Xem bài làm & lời giải →</button>`:empty('Chưa có lượt làm bài nào được lưu.')}</section></div>
 <div class="heading"><h2>Tính năng nổi bật</h2></div><div class="layout-three">${feature('🎯','Chẩn đoán phương án nhiễu','Lời giải đúng; vì sao một lựa chọn sai thường hấp dẫn; giả thuyết lỗi được gắn nhãn rõ ràng.')}${feature('🧭','Lộ trình sửa lỗi','Đề xuất câu hỏi bổ trợ từ những kỹ năng chưa thành thạo, có thể làm lại và so sánh.')}${feature('📈','Minh chứng học tập','Lưu nguyên bản câu hỏi lúc nộp, câu trả lời, điểm, mã lỗi và lịch sử học tập.')}</div>
 <p class="floating-note">Dữ liệu của các hồ sơ demo chỉ lưu trong trình duyệt đang sử dụng. Không sử dụng để quản lý thông tin học sinh thật khi chưa có hệ thống xác thực và máy chủ bảo mật.</p>`}
function feature(icon,title,body){return `<article class="feature"><div class="feature-icon">${icon}</div><div><h3>${esc(title)}</h3><p>${esc(body)}</p></div></article>`}
function chooser(prefix,grade,chapter,type,level,count){const chapters=bank.curriculum[String(grade)]||[];return `<div class="form-grid four"><div class="form-field"><label>Khối lớp</label><select class="form-control" id="${prefix}-grade"><option value="10" ${grade==10?'selected':''}>Hóa học 10</option><option value="11" ${grade==11?'selected':''}>Hóa học 11</option><option value="12" ${grade==12?'selected':''}>Hóa học 12</option></select></div><div class="form-field"><label>Chương / chủ đề</label><select class="form-control" id="${prefix}-chapter"><option value="all">Tất cả các chương</option>${chapters.map(x=>`<option value="${esc(x)}" ${chapter===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div class="form-field"><label>Hình thức câu hỏi</label><select class="form-control" id="${prefix}-type"><option value="all">Tổng hợp 4 hình thức</option>${['mcq','tf','short','essay'].map(x=>`<option value="${x}" ${type===x?'selected':''}>${typeName(x)}</option>`).join('')}</select></div><div class="form-field"><label>Mức độ</label><select class="form-control" id="${prefix}-level"><option value="all">Tất cả mức độ</option>${engine.levels.map(x=>`<option value="${esc(x)}" ${x===level?'selected':''}>${esc(x)}</option>`).join('')}</select></div></div><div class="form-field" style="max-width:220px"><label>Số câu tối đa</label><select class="form-control" id="${prefix}-count">${[5,8,10,15,20,30].map(x=>`<option value="${x}" ${Number(count)===x?'selected':''}>${x} câu</option>`).join('')}</select></div>`}
function renderPractice(){return pageHeader('PRACTICE ENGINE','Luyện tập & kiểm tra cá nhân hóa','Chọn khối lớp, nội dung, mức độ, hình thức và số câu. Đáp án chỉ xuất hiện sau khi nộp bài.')+`<section class="card"><h3>Thiết lập bài luyện</h3><form id="practice-form">${chooser('practice',ui.grade,ui.chapter,ui.type,ui.level,ui.count)}<div class="callout"><strong>Chấm tự động có kiểm tra:</strong> trắc nghiệm nhiều phương án, Đúng/Sai (theo từng ý) và trả lời ngắn số. Tự luận được giữ trạng thái <b>chờ giáo viên chấm</b>.</div><div class="btn-row"><button type="submit" class="btn primary">Tạo và làm bài →</button><button type="button" class="btn secondary" data-action="quick-practice">Luyện nhanh 5 câu</button></div></form></section>
<div class="heading"><h2>Bốn hình thức đánh giá</h2></div><div class="layout-three">${feature('◉','Trắc nghiệm A–D','Chỉ rõ đáp án đúng; phân tích phương án nhiễu theo nhóm lỗi sai.')}${feature('☑','Đúng / Sai','Chấm độc lập bốn nhận định và giải thích từng ý.')}${feature('∑','Trả lời ngắn & tự luận','Đáp số được kiểm tra theo sai số; tự luận do giáo viên duyệt.')}</div>`}
function renderExams(){const items=state.assignments.filter(a=>a.status!=='archived');return pageHeader('ASSESSMENT','Đề kiểm tra & bài được giao','Giáo viên có thể tạo đề từ ngân hàng, trộn thứ tự câu hỏi; học sinh chọn đề để làm. Dữ liệu dùng chung trong một trình duyệt demo.')+`${items.length?`<div class="stack">${items.map(a=>`<article class="card"><div class="card-head"><h3>${esc(a.title)}</h3>${pill('Hóa '+a.grade,'n')}</div><p class="small subtle">${a.questions.length} câu · ${date(a.createdAt)} · Đã lưu phiên bản câu hỏi tại thời điểm giao.</p><div class="btn-row"><button class="btn primary" data-action="start-assignment" data-id="${a.id}">Làm đề này</button>${state.role!=='student'?`<button class="btn danger" data-action="archive-assignment" data-id="${a.id}">Ẩn đề</button>`:''}</div></article>`).join('')}</div>`:empty('Chưa có đề do giáo viên giao. Bạn có thể làm bài luyện trong mục Luyện tập thông minh.','practice')}
${state.role!=='student'?`<div class="heading"><h2>Tạo đề từ ngân hàng</h2></div><section class="card"><form id="assignment-form"><div class="form-field"><label>Tên bài kiểm tra</label><input class="form-control" name="title" required placeholder="Ví dụ: Giữa kì I – Hóa học 11" maxlength="130"></div>${chooser('assignment',11,'all','all','all',10)}<button class="btn teal" type="submit">Tạo và trộn đề kiểm tra</button></form></section>`:''}`}
function questionWidget(q,i,a){let body='';if(q.type==='mcq')body=`<div class="answer-options">${q.options.map((o,j)=>`<label class="opt"><input type="radio" name="q-${esc(q.id)}" value="${j}" ${String(a)==String(j)?'checked':''}><span class="opt-key">${'ABCD'[j]}</span><span>${esc(o)}</span></label>`).join('')}</div>`;
else if(q.type==='tf')body=q.statements.map((s,j)=>`<div class="tf-statement"><span><b>${'abcd'[j]})</b> ${esc(s)}</span><div class="tf-buttons"><label><input type="radio" name="tf-${esc(q.id)}-${j}" value="T" ${a?.[j]==='T'?'checked':''}> Đúng</label><label><input type="radio" name="tf-${esc(q.id)}-${j}" value="F" ${a?.[j]==='F'?'checked':''}> Sai</label></div></div>`).join('');
else if(q.type==='short')body=`<div class="form-field"><label>Nhập đáp số</label><input class="form-control" name="short-${esc(q.id)}" value="${esc(a||'')}" inputmode="decimal" placeholder="Ví dụ: 0,25" style="max-width:350px"><small class="help">Chỉ nhập số, không nhập đơn vị.</small></div>`;
else body=`<div class="form-field"><label>Trình bày các bước giải</label><textarea class="form-control" name="essay-${esc(q.id)}" rows="5" placeholder="Viết phương trình và lập luận của em...">${esc(a||'')}</textarea><small class="help">Giáo viên chấm theo rubric sau khi nộp.</small></div>`;
return `<div class="question-card"><div class="question-top"><span class="question-num">CÂU ${i+1} / ${state.activeQuiz.questions.length}</span><div class="pills">${levelChip(q.level)}${pill(typeName(q.type))}</div></div><p class="stem">${esc(q.stem)}</p>${body}</div>`}
function quizView(){const a=state.activeQuiz;return pageHeader('ĐANG LÀM BÀI',a.title,`Hóa học ${a.grade} · ${a.questions.length} câu · Nộp bài để xem đáp án, điểm và lời giải.`)+`<div class="exam-banner"><div><strong>◷ Phiên làm bài đang hoạt động</strong><p>Hệ thống chỉ lưu câu trả lời khi em nộp bài. Có thể chọn bỏ trống câu chưa chắc chắn.</p></div><button class="btn secondary sm" data-action="cancel-quiz">Hủy bài</button></div><form id="quiz-form">${a.questions.map((q,i)=>questionWidget(q,i,a.answers[q.id])).join('')}<div class="page-actions"><button class="btn teal" type="submit">Nộp bài & xem phân tích →</button></div></form>`}
function answerSummary(q,r,original){const cols=q.type==='mcq'?`<p><b>Phương án:</b> ${q.options.map((t,i)=>`<span style="display:block;margin:5px 0">${'ABCD'[i]}. ${esc(t)}${i===q.correct?' <b style="color:#0c947f">✓ Đáp án đúng</b>':''}${String(original)===String(i)?' <b style="color:#3369c2">· Em đã chọn</b>':''}</span>`).join('')}</p>`:q.type==='tf'?`<div>${q.statements.map((s,i)=>`<p>${'abcd'[i]}) ${esc(s)} — <b>Đáp án: ${q.correct[i]?'Đúng':'Sai'}</b> · ${esc(q.statementExplanations[i])}</p>`).join('')}</div>`:'';
return `<article class="question-review"><div class="card-head"><div class="pills">${pill(q.id)}${levelChip(q.level)}${pill(typeName(q.type))}</div><span class="chip ${r.pending?'pending':r.correct?'pass':'fail'}">${r.pending?'Chờ chấm':r.correct?'Đúng':`Đạt ${number(r.earned)}/1 điểm câu`}</span></div><p class="stem">${esc(q.stem)}</p>${cols}<div class="review ${r.pending?'':r.correct?'pass':'fail'}"><b>Bài làm: ${esc(r.answerText)} · Đáp án: ${esc(r.correctText)}</b>${q.type==='essay'?`<p><b>Rubric để giáo viên chấm:</b></p><ul>${(q.rubric||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:`<p><strong>HƯỚNG DẪN GIẢI</strong></p><p>${esc(q.explanation||'')}</p>`}${r.diagnostics?.length?`<p><strong>PHÂN TÍCH LỖI / BẪY PHƯƠNG ÁN</strong></p>${r.diagnostics.map(d=>`<p>${d.code?`<span class="chip fail">${esc(d.code)}</span> `:''}${esc(d.text)} <em>(${esc(d.confidence)})</em></p>`).join('')}`:''}${q.tip&&!r.pending?`<p><b>Ghi nhớ – mẹo:</b> ${esc(q.tip)}</p>`:''}</div></article>`}
function renderResult(){const a=state.attempts.find(x=>x.id===ui.attemptId)||attempts().at(-1);if(!a)return renderOverview();const issues=a.results.reduce((arr,r)=>arr.concat(r.diagnostics||[]),[]);return pageHeader('BÁO CÁO BÀI LÀM',a.title,`Học sinh: ${a.studentName} · ${date(a.createdAt)} · Câu hỏi và đáp án được lưu bản chụp để đảm bảo tính nhất quán.`)+`<div class="layout-two"><section class="card" style="text-align:center"><h3>Điểm bài làm</h3><div class="score-ring"><div><strong>${number(a.score)}</strong><small>/ 10 điểm</small></div></div><div class="pills" style="justify-content:center">${pill(a.graded?'Đã chấm đầy đủ':'Điểm tạm tính',''+(a.graded?'pass':'pending'))}${a.pendingCount?pill(`${a.pendingCount} câu đang chờ giáo viên chấm`,'pending'):''}</div><p class="footnote">${a.pendingCount?`Điểm tạm tính hiện tại tính các điểm đã chấm, câu tự luận chưa chấm tạm tính 0. Điểm có thể thay đổi khi giáo viên duyệt.`:'Điểm quy đổi trên thang 10 từ tổng điểm từng câu, trong đó các ý Đúng/Sai được chia đều.'}</p></section><section class="card"><h3>Thống kê và minh chứng</h3><div class="mini-grid"><div><b>${a.questions.length}</b><span>Câu hỏi</span></div><div><b>${a.incorrect}</b><span>Câu chưa đúng</span></div><div><b>${issues.length}</b><span>Dấu hiệu cần xem lại</span></div></div><p class="p-lead">Kết quả được chấm theo đáp án đã duyệt và quy tắc định lượng. Mã lỗi từ một lựa chọn chỉ là <b>giả thuyết</b>, chưa xác nhận nguyên nhân tư duy của học sinh.</p><div class="btn-row"><button class="btn teal" data-nav="learning">Luyện tập sửa lỗi →</button><button class="btn secondary" data-action="print">In / Lưu PDF</button></div></section></div><div class="heading"><h2>Đáp án, lời giải và phân tích chi tiết từng câu</h2></div>${a.questions.map((q,i)=>answerSummary(q,a.results[i],a.answers[q.id])).join('')}<div class="btn-row"><button class="btn primary" data-nav="practice">Làm bài khác</button><button class="btn secondary" data-nav="mistakes">Xem bản đồ lỗi sai</button></div>`}
function renderMistakes(){const mine=attempts();const m=engine.mastery(state.attempts,state.studentId);const ds=[];for(const a of mine){a.questions.forEach((q,i)=>{const r=a.results?.[i];if(r?.diagnostics?.length)for(const d of r.diagnostics)ds.push({...d,question:q,attempt:a});})};const counts={};ds.forEach(x=>{const k=x.code||'CHƯA PHÂN LOẠI';counts[k]=(counts[k]||0)+1});const sorted=Object.entries(counts).sort((a,b)=>b[1]-a[1]);return pageHeader('ERROR MAP','Bản đồ lỗi sai Hóa học','Gắn minh chứng phương án/đáp số, phân loại 16 mã lỗi và hiển thị trạng thái xác tín của suy luận.')+`<div class="metrics">${metric('☷',mine.length,'Lượt bài đã nộp')}${metric('◎',ds.length,'Dấu hiệu sai đã ghi nhận','amber')}${metric('▥',sorted.length,'Nhóm lỗi có dữ liệu','purple')}${metric('↗',m.filter(x=>x.percent>=80).length,'Kỹ năng đạt ≥80%','teal')}</div><div class="layout-two" style="margin-top:20px"><section class="card"><h3>Nhóm lỗi xuất hiện nhiều</h3>${sorted.length?sorted.slice(0,8).map(([k,v])=>`<div class="list-row"><div><b>${esc(k)}</b> <span class="small subtle">${esc(bank.errorCatalog[k]?.[0]||'Cần thêm bằng chứng')}</span></div><span class="chip fail">${v}</span></div>`).join(''):empty('Chưa ghi nhận sai lệch nào.','practice')}</section><section class="card"><h3>Thành thạo theo kỹ năng</h3>${m.length?m.slice(0,10).map(x=>progress(x.skill,x.percent,`${x.items} câu · ${x.reliability}`)).join(''):empty('Làm bài đầu tiên để xây dựng bản đồ năng lực.','practice')}</section></div><div class="heading"><h2>Nhật ký dấu hiệu lỗi sai</h2></div>${ds.length?`<div class="stack">${ds.slice().reverse().slice(0,24).map(d=>`<div class="card"><div class="card-head"><div class="pills">${pill(d.code||'Chưa xác định','fail')}${pill('Hóa '+d.question.grade)}${pill(d.question.skill)}</div><small class="subtle">${date(d.attempt.createdAt)}</small></div><p class="small"><strong>${esc(d.question.stem)}</strong></p><p class="p-lead">${esc(d.text)}</p><div class="callout warning"><b>Mức chứng cứ:</b> ${esc(d.confidence)}. ${esc(d.evidence||'Cần thêm bài giải để xác nhận nguyên nhân.')}</div></div>`).join('')}</div>`:empty('Chưa có dữ liệu lỗi sai.','practice')}<div class="heading"><h2>Hệ mã lỗi chuẩn 1.1 — 16 nhóm</h2></div><div class="card"><div class="table-scroll"><table class="data-table"><thead><tr><th>Mã</th><th>Nhóm</th><th>Dấu hiệu lỗi</th></tr></thead><tbody>${Object.entries(bank.errorCatalog).map(([k,v])=>`<tr><td><b>${k}</b></td><td>${esc(v[1])}</td><td>${esc(v[0])}</td></tr>`).join('')}</tbody></table></div></div>`}
function renderLearning(){const plan=engine.plan(state.attempts,allQuestions(),state.studentId,Number(student().grade));const m=engine.mastery(state.attempts,state.studentId).slice(0,7);const personal=attempts();const last=personal.at(-1);const prePost=state.interventions.filter(x=>x.studentId===state.studentId);
 return pageHeader('LEARNING PATH','Lộ trình học cá nhân hóa','Cơ chế quy tắc ưu tiên nội dung có kết quả thấp, chọn bài phù hợp và yêu cầu đánh giá lại. Không kết luận năng lực vững chắc chỉ từ một câu.')+`<div class="layout-two"><section class="card"><h3>Chu trình khắc phục lỗi sai</h3><div class="plan-step"><strong>01 · Xác định dấu hiệu sai</strong><p>Đối chiếu bài làm đã nộp với đáp án, phân tích những phương án nhiễu có cơ chế rõ ràng.</p></div><div class="plan-step"><strong>02 · Chẩn đoán có điều kiện</strong><p>Gán giả thuyết mã lỗi; phân biệt bằng chứng trả lời sai và suy đoán về nguyên nhân.</p></div><div class="plan-step"><strong>03 · Chọn bài củng cố</strong><p>Ưu tiên kỹ năng có kết quả thấp; tăng dần nhận biết → thông hiểu → vận dụng.</p></div><div class="plan-step"><strong>04 · Kiểm tra lại và lưu minh chứng</strong><p>Ghi nhận lần luyện tiếp theo; không ghi tiến bộ khi chưa có bài làm mới.</p></div></section><section class="card"><h3>Định hướng hiện tại</h3><div class="callout ${plan.hasHistory?'':'warning'}">${esc(plan.summary)}</div>${plan.targets.length?`<p class="small"><b>Kỹ năng cần ưu tiên:</b></p><div class="pills">${plan.targets.map(x=>pill(x,'v')).join('')}</div>`:''}${m.length?m.map(x=>progress(x.skill,x.percent,`${x.items} câu được ghi nhận`)).join(''):''}<p class="footnote">Đã có ${personal.length} bài làm; ${prePost.length} lượt kích hoạt bài luyện theo lộ trình. Kết quả phản ánh dữ liệu thực có trong trình duyệt này.</p></section></div><div class="heading"><h2>Gói luyện tập đề xuất · Hóa học ${student().grade}</h2></div><div class="card">${plan.items.length?plan.items.map((q,i)=>`<div class="list-row"><div><div class="list-title">${i+1}. ${esc(q.skill)} · ${esc(q.chapter)}</div><p class="tiny subtle" style="margin:4px 0">${esc(q.stem)}</p><div class="pills">${levelChip(q.level)}${pill(typeName(q.type))}</div></div></div>`).join('')+`<div class="btn-row"><button class="btn teal" data-action="start-plan">Bắt đầu gói học bù ${plan.items.length} câu →</button></div>`:empty('Chưa có câu hỏi phù hợp cho khối lớp đã chọn.')}</div><div class="heading"><h2>Minh chứng trước – sau</h2></div><section class="card">${last?`<p class="p-lead"><b>Bài làm gần nhất:</b> ${esc(last.title)} · ${number(last.score)}/10 điểm · ${date(last.createdAt)}.</p>`:''}${prePost.length?prePost.map(p=>{const after=state.attempts.find(a=>a.id===p.afterAttemptId);const before=state.attempts.find(a=>a.id===p.beforeAttemptId);return `<div class="list-row"><div><b class="small">Đợt luyện: ${date(p.createdAt)}</b><div class="small subtle">Trước: ${before?number(before.score)+'/10':'Chưa có điểm'} → Sau: ${after?number(after.score)+'/10':'Chưa nộp bài'}. Đây là hai bài có thể khác độ khó, không dùng chênh lệch như chứng minh nhân quả.</div></div>${after?pill('Đã hoàn thành','pass'):pill('Đang luyện','pending')}</div>`}).join(''):`<div class="callout warning">Chưa có cặp trước – sau. Hãy làm bài chẩn đoán, sau đó làm gói luyện tập cá nhân hóa.</div>`}</section>`}
function renderLibrary(){const gg=ui.libraryGrade;let questions=allQuestions().filter(x=>gg==='all'||String(x.grade)===String(gg));if(ui.libraryChapter!=='all')questions=questions.filter(x=>x.chapter===ui.libraryChapter);return pageHeader('QUESTION BANK','Ngân hàng câu hỏi Hóa học 10–12','Kho câu hỏi minh họa được biên soạn theo định dạng chuẩn, kết nối mức độ, kỹ năng, phương án nhiễu và lời giải.')+`<section class="card"><div class="form-grid"><div class="form-field"><label>Khối lớp</label><select class="form-control" id="lib-grade"><option value="all">Tất cả khối lớp</option>${[10,11,12].map(g=>`<option value="${g}" ${String(gg)===String(g)?'selected':''}>Hóa ${g}</option>`).join('')}</select></div><div class="form-field"><label>Chương</label><select class="form-control" id="lib-chapter"><option value="all">Tất cả chương</option>${(gg==='all'?Object.values(bank.curriculum).flat():bank.curriculum[String(gg)]).filter((x,i,a)=>a.indexOf(x)===i).map(x=>`<option value="${esc(x)}" ${x===ui.libraryChapter?'selected':''}>${esc(x)}</option>`).join('')}</select></div></div><div class="pills">${pill(questions.length+' câu hiển thị','n')}${pill('36 trắc nghiệm + 6 Đ/S + 6 ngắn + 3 tự luận')}${pill('3 khối 10–12')}</div></section><div class="heading"><h2>Danh sách câu hỏi</h2></div><div class="card"><div class="table-scroll"><table class="data-table"><thead><tr><th>Mã</th><th>Khối</th><th>Chương</th><th>Câu hỏi</th><th>Độ khó</th><th>Dạng</th></tr></thead><tbody>${questions.map(q=>`<tr><td><b>${esc(q.id)}</b></td><td>${q.grade}</td><td>${esc(q.chapter)}</td><td>${esc(q.stem)}</td><td>${levelChip(q.level)}</td><td>${esc(typeName(q.type))}</td></tr>`).join('')}</tbody></table></div></div><p class="footnote">Các câu hỏi là nội dung biên soạn minh họa; nhãn “approved” trong dữ liệu mẫu không thay thế quy trình giáo viên thẩm định trước kiểm tra chính thức. Ngân hàng có thể bổ sung trực tiếp ở khu vực giáo viên.</p>`}
function renderTeacher(){if(state.role==='student')return renderOverview();let tab=ui.teacherTab;const btns=['dashboard','author','grade','class'].map((id,i)=>`<button class="tab ${tab===id?'selected':''}" data-action="teacher-tab" data-id="${id}">${['Tổng quan lớp','Soạn câu hỏi','Duyệt tự luận','Quản lý hồ sơ'][i]}</button>`).join('');let body='';
 if(tab==='dashboard'){const scores=state.attempts.filter(a=>a.graded),av=scores.length?number(scores.reduce((s,a)=>s+a.score,0)/scores.length):'—';const byStudent=state.students.map(st=>{const aa=state.attempts.filter(x=>x.studentId===st.id);return {st,aa}});body=`<div class="metrics">${metric('♙',state.students.length,'Hồ sơ học sinh demo')}${metric('▤',state.attempts.length,'Tổng lượt nộp bài','teal')}${metric('◷',state.attempts.reduce((s,a)=>s+(a.pendingCount||0),0),'Câu tự luận chờ duyệt','amber')}${metric('◉',scores.length?`${av}/10`:'—','Điểm TB bài chấm đầy đủ','purple')}</div><div class="heading"><h2>Bảng theo dõi lớp</h2></div><section class="card"><div class="table-scroll"><table class="data-table"><thead><tr><th>Hồ sơ</th><th>Khối</th><th>Bài đã làm</th><th>Điểm gần nhất</th><th>Đúng/Sai & gợi ý</th></tr></thead><tbody>${byStudent.map(x=>{const last=x.aa.at(-1);return `<tr><td><b>${esc(x.st.name)}</b></td><td>${x.st.grade}</td><td>${x.aa.length}</td><td>${last?number(last.score)+'/10':'—'}</td><td>${last?`${last.incorrect} câu chưa đạt; ${last.graded?'đã chấm đủ':'cần chấm tự luận'}`:'Chưa có kết quả'}</td></tr>`}).join('')}</tbody></table></div></section>`}
 if(tab==='author'){body=`<div class="callout">Mọi câu hỏi được lưu trong trình duyệt này. Câu tự biên soạn chỉ có thể dùng thử sau khi người tạo nhập đầy đủ dữ kiện, đáp án và lời giải; chưa được kiểm định độc lập.</div><div class="heading"><h2>Biên soạn câu hỏi mới</h2></div><section class="card"><form id="author-form"><div class="form-grid"><div class="form-field"><label>Khối lớp</label><select class="form-control" name="grade" id="author-grade"><option value="10">Hóa 10</option><option value="11" selected>Hóa 11</option><option value="12">Hóa 12</option></select></div><div class="form-field"><label>Chương</label><select class="form-control" name="chapter" id="author-chapter">${bank.curriculum['11'].map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div class="form-field"><label>Mức độ</label><select class="form-control" name="level">${engine.levels.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div class="form-field"><label>Loại câu</label><select class="form-control" name="type" id="author-type"><option value="mcq">Nhiều phương án</option><option value="tf">Đúng / Sai</option><option value="short">Trả lời ngắn</option><option value="essay">Tự luận</option></select></div></div><div class="form-field"><label>Kỹ năng đánh giá</label><input class="form-control" name="skill" required placeholder="Ví dụ: Bảo toàn electron" maxlength="120"></div><div class="form-field"><label>Nội dung câu hỏi</label><textarea class="form-control" name="stem" required maxlength="2500" placeholder="Ghi đầy đủ dữ kiện, điều kiện, đơn vị..."></textarea></div><div id="author-type-fields">${authorFields('mcq')}</div><div class="form-field"><label>Lời giải chuẩn và lập luận</label><textarea class="form-control" name="explanation" required placeholder="Nhận diện bản chất → phương trình → tính toán → kết luận"></textarea></div><button class="btn primary" type="submit">Lưu bản nháp câu hỏi</button></form></section><div class="heading"><h2>Ngân hàng câu hỏi do giáo viên soạn</h2></div><section class="card">${state.customQuestions.length?state.customQuestions.map(q=>`<div class="list-row"><div><b>${esc(q.id)}</b> · ${esc(q.stem)}<div class="tiny subtle">${esc(q.chapter)} · ${esc(typeName(q.type))}</div></div>${q.approved?pill('Đã duyệt','pass'):`<button class="btn sm teal" data-action="approve-question" data-id="${q.id}">Xác nhận kiểm duyệt</button>`}</div>`).join(''):empty('Chưa có câu hỏi do giáo viên biên soạn.')}</section>`}
 if(tab==='grade'){const tasks=state.attempts.flatMap(a=>a.questions.map((q,i)=>({a,q,i,r:a.results?.[i]}))).filter(x=>x.r?.pending);body=tasks.length?tasks.map(x=>`<div class="card" style="margin:14px 0"><div class="card-head"><h3>${esc(x.a.studentName)} · ${esc(x.q.id)}</h3>${pill('Chờ duyệt','pending')}</div><p class="p-lead"><b>Đề:</b> ${esc(x.q.stem)}</p><div class="output">${esc(x.a.answers[x.q.id]||'(Học sinh bỏ trống)')}</div><div class="review"><b>Rubric tham khảo:</b><ul>${(x.q.rubric||[]).map(s=>`<li>${esc(s)}</li>`).join('')}</ul></div><div class="form-field" style="max-width:230px"><label>Điểm câu (0–1)</label><input type="number" class="form-control" min="0" max="1" step="0.25" value="0" id="review-${x.a.id}-${x.i}"></div><button class="btn teal" data-action="grade-essay" data-attempt="${x.a.id}" data-index="${x.i}">Duyệt và lưu điểm</button></div>`).join(''):empty('Không có câu tự luận đang chờ giáo viên chấm.');}
 if(tab==='class'){body=`<section class="card"><h3>Danh sách hồ sơ demo</h3>${state.students.map(s=>`<div class="list-row"><div><b>${esc(s.name)}</b><div class="small subtle">${esc(s.id)} · Hóa ${s.grade}</div></div>${pill('Hồ sơ cục bộ','n')}</div>`).join('')}<form id="student-add-form" class="form-grid" style="margin-top:23px"><div class="form-field"><label>Tên hồ sơ mới</label><input class="form-control" name="name" maxlength="80" required placeholder="VD: Học sinh demo D" /></div><div class="form-field"><label>Khối lớp</label><select class="form-control" name="grade"><option value="10">10</option><option value="11" selected>11</option><option value="12">12</option></select></div><div><button class="btn primary" type="submit">Thêm hồ sơ</button></div></form><div class="btn-row"><button class="btn secondary" data-action="random-student">Gọi ngẫu nhiên một học sinh</button></div></section>`}
 return pageHeader('TEACHER WORKSPACE','Không gian giáo viên','Quản trị ngân hàng câu hỏi, xem minh chứng trong cùng trình duyệt demo, chấm tự luận và giao nhiệm vụ học bù.')+`<div class="switch-tabs">${btns}</div><div style="margin-top:19px">${body}</div>`}
function authorFields(type){if(type==='mcq')return `<div class="form-grid">${'ABCD'.split('').map((x,i)=>`<div class="form-field"><label>Phương án ${x}</label><input class="form-control" name="opt${i}" required></div>`).join('')}</div><div class="form-field"><label>Đáp án đúng</label><select class="form-control" name="correctMcq">${'ABCD'.split('').map((x,i)=>`<option value="${i}">${x}</option>`).join('')}</select></div><div class="form-field"><label>Giả thuyết lỗi sai theo phương án nhiễu (tùy chọn)</label><textarea class="form-control" name="distractors" placeholder="Ví dụ: A:K01:Nhầm khái niệm; C:T01:Nhầm tỉ lệ mol"></textarea></div>`;
 if(type==='tf')return `<div class="form-field"><label>Bốn nhận định (mỗi dòng một ý)</label><textarea class="form-control" name="statements" required rows="4"></textarea></div><div class="form-field"><label>Đáp án đúng theo thứ tự: Đ,S,Đ,S</label><input class="form-control" name="correctTf" required placeholder="Đ,S,Đ,S" /></div><div class="form-field"><label>Giải thích từng ý (mỗi dòng một giải thích)</label><textarea class="form-control" name="statementExplanations" rows="4" required></textarea></div>`;
 if(type==='short')return `<div class="form-grid"><div class="form-field"><label>Đáp số dạng số</label><input class="form-control" type="number" step="any" required name="correctShort" placeholder="0.25" /></div><div class="form-field"><label>Sai số chấp nhận (tuyệt đối)</label><input class="form-control" type="number" step="any" min="0" name="tolerance" value="0.001" required></div></div>`;
 return `<div class="form-field"><label>Rubric (mỗi dòng một tiêu chí chấm)</label><textarea class="form-control" name="rubric" rows="4" required placeholder="Viết phương trình cân bằng\nLập luận hóa học\nKết luận"></textarea></div>`}
function renderReports(){const aa=state.attempts;const confirmed=aa.filter(x=>x.graded);const avg=confirmed.length?number(confirmed.reduce((s,a)=>s+a.score,0)/confirmed.length):'—';return pageHeader('LEARNING EVIDENCE','Báo cáo thống kê & minh chứng','Xuất thống kê CSV theo từng lượt bài làm hoặc sao lưu JSON đầy đủ. Không suy diễn hiệu quả sư phạm khi chưa có thiết kế thực nghiệm phù hợp.')+`<div class="metrics">${metric('▤',aa.length,'Tổng lượt làm bài')}${metric('✓',confirmed.length,'Bài đã chấm đủ','teal')}${metric('◷',aa.length-confirmed.length,'Bài chờ duyệt','amber')}${metric('◉',avg==='—'?'—':avg+'/10','Điểm TB bài chấm đủ','purple')}</div><div class="heading"><h2>Xuất dữ liệu và bảng tổng hợp</h2></div><div class="tool-banner"><div><b>CSV lượt bài làm (không có tên thật)</b><p>Thời điểm · hồ sơ demo · điểm · trạng thái · số câu · mã lỗi gợi ý.</p></div><button class="btn primary" data-action="export-csv">Xuất CSV</button></div><div class="card" style="margin-top:18px"><div class="table-scroll"><table class="data-table"><thead><tr><th>Ngày giờ</th><th>Hồ sơ</th><th>Bài làm</th><th>Điểm/10</th><th>Trạng thái</th><th>Chưa đúng</th></tr></thead><tbody>${aa.length?aa.slice().reverse().map(a=>`<tr><td>${date(a.createdAt)}</td><td>${esc(a.studentName)}</td><td>${esc(a.title)}</td><td>${number(a.score)}</td><td>${a.graded?pill('Đã chấm','pass'):pill('Chờ chấm','pending')}</td><td>${a.incorrect}</td></tr>`).join(''):`<tr><td colspan="6">Chưa có bài làm được lưu.</td></tr>`}</tbody></table></div></div><div class="heading"><h2>Nguyên tắc sử dụng số liệu</h2></div><div class="callout warning">Điểm tăng qua hai bài khác nhau không đủ chứng minh tác động của WebApp. Cần thiết kế bài đo tương đương, thống nhất tiêu chí đánh giá, ghi nhận thời gian can thiệp và đối chiếu trước–sau, có thể có nhóm so sánh. Không báo cáo dữ liệu demo thành dữ liệu học sinh thực.</div>`}
function renderAdmin(){return pageHeader('SYSTEM & BACKUP','Dữ liệu & quản trị bản demo','Vận hành toàn bộ tính năng cốt lõi trong trình duyệt không cần GEMINI_API_KEY. Các hồ sơ chỉ là dữ liệu giả lập, chưa có máy chủ hay phân quyền an toàn.')+`<div class="layout-two"><div class="card"><h3>Sao lưu và phục hồi</h3><p class="p-lead">Tải toàn bộ bài làm, câu hỏi đã thêm, rubric, câu giao và lịch sử luyện dưới dạng JSON.</p><div class="btn-row"><button class="btn primary" data-action="export-json">Xuất dữ liệu JSON</button><label class="btn secondary" for="backup-input" style="cursor:pointer">Nhập tệp JSON…</label><input id="backup-input" type="file" accept=".json,application/json" style="display:none"></div><div class="divider"></div><h3>Xóa dữ liệu cục bộ</h3><p class="small subtle">Khôi phục 3 hồ sơ demo mặc định; ngân hàng câu hỏi chuẩn vẫn được giữ lại.</p><button class="btn danger" data-action="reset">Đặt lại bản demo</button></div><div class="card"><h3>Trạng thái kiến trúc</h3><div class="list-row"><span class="small">Động cơ chấm theo đáp án chuẩn</span>${pill('Hoạt động','pass')}</div><div class="list-row"><span class="small">Phân tích phương án nhiễu</span>${pill('Quy tắc','pass')}</div><div class="list-row"><span class="small">Cá nhân hóa bài luyện</span>${pill('Quy tắc','pass')}</div><div class="list-row"><span class="small">Dịch vụ mô hình AI sinh nội dung</span>${pill('Chưa tích hợp','pending')}</div><div class="list-row"><span class="small">Xác thực & CSDL nhiều thiết bị</span>${pill('Chưa tích hợp','pending')}</div><div class="list-row"><span class="small">Ghi dấu chấm tự luận giáo viên</span>${pill('Hoạt động nội bộ','pass')}</div></div></div><div class="heading"><h2>Quy định bảo mật trước khi sử dụng thật</h2></div><div class="callout warning">Chức năng chọn vai trò trong demo chỉ đổi giao diện và không phải xác thực danh tính. Không nhập tên thật, dữ liệu cá nhân hoặc hồ sơ học tập thật của học sinh vào bản tĩnh này. Muốn triển khai nhiều người dùng cần bổ sung cơ sở dữ liệu an toàn, xác thực, phân quyền phía máy chủ, sao lưu và chính sách dữ liệu.</div>`}
function renderAbout(){return pageHeader('ABOUT THE PROJECT','CHEM-MAP TUTOR AI 2.0','Hệ sinh thái chẩn đoán – phân tích – khắc phục lỗi sai Hóa học THPT được xây dựng cho minh họa và thử nghiệm kỹ thuật.')+`<div class="welcome" style="margin-bottom:20px"><div><div class="eyebrow">TÁC GIẢ GIẢI PHÁP</div><h1>Lê Bá Nhẫn<br>Trường THPT Hòn Đất</h1><p>Hóa học 10 – 11 – 12 · Chương trình GDPT 2018 · Đánh giá bằng minh chứng quá trình học.</p></div><div class="hero-icon" aria-hidden="true"><svg viewBox="0 0 120 120"><path d="M42 13h36M54 13v33L27 94a8 8 0 0 0 7 12h52a8 8 0 0 0 7-12L66 46V13"/><path d="M37 79h46"/><circle cx="51" cy="70" r="4"/><circle cx="69" cy="90" r="5"/><circle cx="62" cy="59" r="2"/></svg></div></div><div class="layout-two"><div class="card"><h3>Quy trình chuyên môn</h3><ol class="checklist"><li>1. Giáo viên kiểm duyệt dữ kiện, đáp án, rubric và phương án nhiễu.</li><li>2. Học sinh làm bài, hệ thống lưu bản chụp câu hỏi và câu trả lời.</li><li>3. Chấm theo quy tắc, hiển thị câu đúng/sai, thang 10 điểm và lời giải.</li><li>4. Liên kết phương án nhiễu với giả thuyết lỗi sai; yêu cầu đối chiếu bằng chứng.</li><li>5. Sinh bài luyện phù hợp, lưu điểm trước và sau; giáo viên nhận định kết quả.</li></ol></div><div class="card"><h3>Phân biệt phiên bản demo với sản phẩm triển khai</h3><p class="p-lead"><b>Đã hoạt động:</b> chấm câu A–D, Đúng/Sai, trả lời ngắn; giáo viên chấm tự luận; 16 mã lỗi; lộ trình luyện; ngân hàng câu hỏi, đề giao, thống kê và sao lưu.</p><p class="p-lead"><b>Chưa có:</b> đăng nhập thật, đồng bộ nhiều máy, kiểm tra chống gian lận, AI suy luận mở có model ngoài, báo cáo hiệu quả từ thực nghiệm thật.</p></div></div><div class="heading"><h2>Công nghệ và trách nhiệm khoa học</h2></div><div class="card"><div class="pills">${pill('HTML / CSS / JavaScript')}${pill('LocalStorage')}${pill('Không cần API key')}${pill('16 mã lỗi')}${pill('Hóa 10 / 11 / 12')}</div><p class="p-lead">Động cơ hiện tại là hệ luật chuyên môn có thể kiểm toán, không giả mạo API trí tuệ nhân tạo. Những lỗi sai phỏng đoán từ phương án nhiễu được hiển thị là <b>giả thuyết</b>; giáo viên là người xác nhận nguyên nhân và chịu trách nhiệm đánh giá chính thức.</p></div>`}
// Actions
function makeQuiz(qs,title,mode,grade,assignmentId=null,interventionId=null){if(!qs.length){toast('Chưa có câu hỏi phù hợp bộ lọc.');return;}state.activeQuiz={id:'quiz-'+code(),title,mode,grade:Number(grade),assignmentId,interventionId,questions:qs.map(x=>JSON.parse(JSON.stringify(x))),answers:{},startedAt:new Date().toISOString()};persist();render();window.scrollTo(0,0)}
function selectedQs(prefix){const grade=Number(el(prefix+'-grade').value),chapter=el(prefix+'-chapter').value,type=el(prefix+'-type').value,level=el(prefix+'-level').value,count=Math.max(1,Math.min(30,Number(el(prefix+'-count').value)||8));return {grade,chapter,type,level,count,questions:engine.shuffle(allQuestions().filter(q=>q.grade===grade&&(chapter==='all'||q.chapter===chapter)&&(type==='all'||q.type===type)&&(level==='all'||q.level===level))).slice(0,count)};}
function addStudent(form){const fd=new FormData(form),name=String(fd.get('name')||'').trim(),grade=Number(fd.get('grade'));if(!name||name.length>80)return toast('Tên hồ sơ không hợp lệ.');state.students.push({id:'hs-'+code(),name,grade});persist();render();toast('Đã thêm hồ sơ dùng thử.');}
function createQuestion(form){const fd=new FormData(form),raw=k=>String(fd.get(k)||'').trim();const type=raw('type');let q={id:'CUSTOM-'+code(),grade:Number(raw('grade')),chapter:raw('chapter'),level:raw('level'),skill:raw('skill'),stem:raw('stem'),type,explanation:raw('explanation'),source:'Do giáo viên demo biên soạn; cần kiểm duyệt khoa học',approved:false};
 if(type==='mcq'){q.options=[0,1,2,3].map(i=>raw('opt'+i));q.correct=Number(raw('correctMcq'));q.distractors={};for(const seg of raw('distractors').split(';')){const [key,err,...msg]=seg.split(':').map(s=>s.trim());const j='ABCD'.indexOf(key?.toUpperCase());if(j>=0&&j!==q.correct&&bank.errorCatalog[err])q.distractors[String(j)]={code:err,hypothesis:msg.join(':')||bank.errorCatalog[err][0]}}}
 else if(type==='tf'){q.statements=raw('statements').split(/\r?\n/).filter(Boolean);const tt=raw('correctTf').split(/[,;\s]+/).filter(Boolean).map(x=>x.toUpperCase());if(tt.length!==4||tt.some(x=>!['Đ','D','S','T','F'].includes(x)))return toast('Đáp án Đúng/Sai cần 4 giá trị Đ,S,...');q.correct=tt.map(x=>['Đ','D','T'].includes(x));q.statementExplanations=raw('statementExplanations').split(/\r?\n/).filter(Boolean);if(q.statementExplanations.length!==4)return toast('Cần đúng 4 giải thích cho 4 nhận định.');}
 else if(type==='short'){q.correct=Number(raw('correctShort'));q.tolerance=Number(raw('tolerance'));q.defaultError='T01';}
 else q.rubric=raw('rubric').split(/\r?\n/).filter(Boolean);
 const invalid=engine.validateQuestion(q);if(invalid)return toast(invalid);if(q.type==='mcq'&&q.options.some(x=>!x))return toast('Vui lòng nhập đủ cả 4 phương án.');state.customQuestions.push(q);persist();render();toast('Đã lưu bản nháp. Giáo viên cần kiểm tra và duyệt trước khi đưa vào đề.');}
function scoreExam(form){const active=state.activeQuiz;if(!active)return;const fd=new FormData(form),answers={};for(const q of active.questions){if(q.type==='mcq')answers[q.id]=fd.get('q-'+q.id)??'';else if(q.type==='tf')answers[q.id]=q.statements.map((_,j)=>fd.get('tf-'+q.id+'-'+j)||'');else if(q.type==='short')answers[q.id]=String(fd.get('short-'+q.id)||'').trim();else answers[q.id]=String(fd.get('essay-'+q.id)||'').trim();}
 if(!confirm('Xác nhận nộp bài? Sau khi nộp, hệ thống sẽ hiển thị đáp án và lời giải.'))return;
 const graded=engine.gradeAttempt(active.questions,answers),today=new Date().toISOString();const a={id:'attempt-'+code(),quizId:active.id,title:active.title,mode:active.mode,assignmentId:active.assignmentId,studentId:state.studentId,studentName:student().name,grade:active.grade,createdAt:today,startedAt:active.startedAt,questions:active.questions,answers,...graded};state.attempts.push(a);if(active.interventionId){const i=state.interventions.findIndex(x=>x.id===active.interventionId);if(i>=0)state.interventions[i].afterAttemptId=a.id;}state.latestAttemptId=a.id;state.activeQuiz=null;ui.attemptId=a.id;ui.view='result';persist();renderResultPage();toast('Đã nộp bài và lưu kết quả cục bộ.');}
function renderResultPage(){el('content').innerHTML=renderResult();el('page-heading').textContent='Kết quả bài làm';topnav();window.scrollTo(0,0)}
function addAssignment(form){const selection=selectedQs('assignment');const title=String(new FormData(form).get('title')||'').trim();if(!title){toast('Vui lòng nhập tên đề.');return;}if(!selection.questions.length){toast('Không tìm thấy câu hỏi phù hợp với bộ lọc.');return;}state.assignments.push({id:'exam-'+code(),title,grade:selection.grade,questions:selection.questions.map(q=>JSON.parse(JSON.stringify(q))),createdAt:new Date().toISOString(),status:'active'});persist();render();toast('Đề đã được tạo và trộn thứ tự câu hỏi.');}
function saveFile(name,text,type){const blob=new Blob(['\ufeff'+text],{type});const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),400)}
function csvText(){const columns=['Thời điểm','Hồ sơ demo','Khối','Bài làm','Điểm /10','Trạng thái','Câu chưa đúng','Mã lỗi gợi ý'];const rows=state.attempts.map(a=>[a.createdAt,a.studentName,a.grade,a.title,a.score,a.graded?'Đã chấm':'Chờ chấm',a.incorrect,[...new Set(a.results.flatMap(x=>(x.diagnostics||[]).map(d=>d.code).filter(Boolean)))].join(';')]);return [columns,...rows].map(r=>r.map(x=>'"'+String(x??'').replace(/"/g,'""')+'"').join(',')).join('\r\n')}
function reviewEssay(attemptId,index){const a=state.attempts.find(x=>x.id===attemptId),r=a?.results?.[index];if(!a||!r||!r.pending)return toast('Câu không tồn tại hoặc đã duyệt.');const n=Number(el(`review-${attemptId}-${index}`)?.value);if(!Number.isFinite(n)||n<0||n>1)return toast('Điểm phải thuộc đoạn từ 0 đến 1.');r.earned=n;r.pending=false;r.correct=n===1;r.teacherReviewedAt=new Date().toISOString();r.teacherReviewStatus='Giáo viên đã duyệt';engine.rescore(a);persist();render();toast('Đã lưu điểm câu tự luận và cập nhật điểm bài làm.');}
function startPlan(){const plan=engine.plan(state.attempts,allQuestions(),state.studentId,Number(student().grade));const latest=attempts().at(-1);const id='intervention-'+code();state.interventions.push({id,studentId:state.studentId,createdAt:new Date().toISOString(),beforeAttemptId:latest?.id||null,afterAttemptId:null,skills:plan.targets});makeQuiz(plan.items,'Gói học bù cá nhân hóa · Hóa '+student().grade,'plan',student().grade,null,id);}
function updateChapter(prefix){const grade=Number(el(prefix+'-grade').value),target=el(prefix+'-chapter');target.innerHTML='<option value="all">Tất cả các chương</option>'+bank.curriculum[String(grade)].map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');}
// Event delegation
el('content').addEventListener('click',ev=>{const n=ev.target.closest('[data-nav]');if(n){navigate(n.dataset.nav);return;}const b=ev.target.closest('[data-action]');if(!b)return;const act=b.dataset.action,id=b.dataset.id;
 switch(act){case 'menu':el('sidebar').classList.toggle('open');break;
 case 'quick-practice':{const grade=Number(student().grade);const qs=engine.shuffle(allQuestions().filter(x=>x.grade===grade&&x.type!=='essay')).slice(0,5);makeQuiz(qs,'Luyện nhanh · Hóa '+grade,'practice',grade);break;}
 case 'cancel-quiz':if(confirm('Hủy phiên làm bài? Câu trả lời chưa nộp sẽ không được lưu.')){state.activeQuiz=null;persist();ui.view='practice';render();}break;
 case 'view-attempt':ui.attemptId=id;renderResultPage();break;
 case 'print':window.print();break;
 case 'j-export-teacher':case 'j-export-student':case 'j-copy-prompt':case 'j-reset': {window.CMJigsaw.action(act).then?.(needsRender=>{if(needsRender)render()});break;}
 case 'teacher-tab':ui.teacherTab=id;render();break;
 case 'start-plan':startPlan();break;
 case 'start-assignment':{const a=state.assignments.find(x=>x.id===id);if(a)makeQuiz(a.questions,a.title,'assignment',a.grade,a.id);break;}
 case 'archive-assignment':if(confirm('Ẩn đề kiểm tra này?')){const a=state.assignments.find(x=>x.id===id);if(a)a.status='archived';persist();render();}break;
 case 'grade-essay':reviewEssay(b.dataset.attempt,Number(b.dataset.index));break;
 case 'approve-question':{const q=state.customQuestions.find(x=>x.id===id);if(q&&confirm('Xác nhận đã kiểm tra dữ kiện, công thức, đáp án, lời giải và điều kiện của câu này?')){q.approved=true;q.approvedAt=new Date().toISOString();persist();render();toast('Đã xác nhận kiểm duyệt và đưa câu hỏi vào kho luyện tập.');}break;}
 case 'random-student':toast('Học sinh được gọi: '+state.students[Math.floor(Math.random()*state.students.length)].name);break;
 case 'export-csv':saveFile('CHEM_MAP_Minh_Chung_Bai_Lam.csv',csvText(),'text/csv;charset=utf-8');break;
 case 'export-json':saveFile('CHEM_MAP_Backup_'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify({app:'CHEM-MAP TUTOR AI',schema:1,exportedAt:new Date().toISOString(),data:state},null,2),'application/json;charset=utf-8');break;
 case 'reset':if(confirm('Xóa toàn bộ bài làm, hồ sơ demo bổ sung và câu hỏi tự biên soạn trên trình duyệt này? Hành động không thể hoàn tác.')){state=fresh();ui.view='overview';ui.grade=11;persist();render();toast('Đã đặt lại dữ liệu demo.')}break;
 }
});
document.querySelector('.mobile-menu').addEventListener('click',()=>el('sidebar').classList.toggle('open'));
el('nav-main').addEventListener('click',ev=>{const b=ev.target.closest('[data-nav]');if(b)navigate(b.dataset.nav)});
el('content').addEventListener('submit',ev=>{const form=ev.target;if(!['practice-form','quiz-form','assignment-form','author-form','student-add-form','jigsaw-form'].includes(form.id))return;ev.preventDefault();
 if(form.id==='jigsaw-form'){window.CMJigsaw.capture();toast('Đã lưu nội dung giáo án và phiếu Jigsaw cục bộ.');}
 else if(form.id==='practice-form'){const s=selectedQs('practice');ui.grade=s.grade;ui.chapter=s.chapter;ui.type=s.type;ui.level=s.level;ui.count=s.count;makeQuiz(s.questions,`Bài luyện tổng hợp · Hóa ${s.grade}`,'practice',s.grade);}
 else if(form.id==='quiz-form')scoreExam(form);
 else if(form.id==='assignment-form')addAssignment(form);
 else if(form.id==='author-form')createQuestion(form);
 else if(form.id==='student-add-form')addStudent(form);
});
el('content').addEventListener('change',ev=>{const t=ev.target;if(t.id==='practice-grade'||t.id==='assignment-grade')updateChapter(t.id.split('-')[0]);if(t.id==='lib-grade'){ui.libraryGrade=t.value;ui.libraryChapter='all';render()}if(t.id==='lib-chapter'){ui.libraryChapter=t.value;render()}if(t.id==='author-grade'){el('author-chapter').innerHTML=bank.curriculum[String(t.value)].map(x=>`<option>${esc(x)}</option>`).join('')}if(t.id==='author-type')el('author-type-fields').innerHTML=authorFields(t.value);});
el('role-switch').addEventListener('change',ev=>{if(state.activeQuiz){ev.target.value=state.role;toast('Vui lòng nộp hoặc hủy bài trước khi đổi vai trò.');return;}state.role=ev.target.value;ui.view=state.role==='student'?'overview':'teacher';persist();render()});
el('student-switch').addEventListener('change',ev=>{if(state.activeQuiz){ev.target.value=state.studentId;toast('Nộp hoặc hủy bài trước khi chuyển hồ sơ.');return;}state.studentId=ev.target.value;ui.grade=Number(student().grade);ui.view='overview';persist();render()});
el('backup-input')?.addEventListener('change',()=>{});
el('content').addEventListener('change',async ev=>{if(ev.target.id==='j-source-file'){window.CMJigsaw.importFile(ev.target.files?.[0]);return;}if(ev.target.id!=='backup-input')return;const file=ev.target.files?.[0];if(!file)return;if(file.size>5_000_000){toast('Tệp sao lưu vượt 5 MB.');return;}try{const raw=JSON.parse(await file.text());const data=raw.data;if(raw.app!=='CHEM-MAP TUTOR AI'||raw.schema!==1||!Array.isArray(data.students)||!Array.isArray(data.attempts)||!Array.isArray(data.customQuestions))throw Error('Sai cấu trúc tệp sao lưu.');if(!confirm('Khôi phục tệp này sẽ ghi đè dữ liệu demo hiện tại. Tiếp tục?'))return;state={...fresh(),...data,activeQuiz:null};ui.view='overview';persist();render();toast('Đã khôi phục dữ liệu sao lưu.')}catch(e){toast('Không thể nhập bản sao lưu: '+e.message)}});
render();
})();
